import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { createDb } from "./client.ts";

/** `apps/api/drizzle/`: the SQL migration files generated by drizzle-kit. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/**
 * Applies every migration that hasn't run yet, in order. Safe to run repeatedly:
 * Drizzle records applied migrations in `drizzle.__drizzle_migrations` and skips them.
 * Used by `pnpm db:migrate`, the integration tests, and (later) deployments.
 */
export async function runMigrations(databaseUrl: string): Promise<void> {
  const { db, pool } = createDb(databaseUrl);
  try {
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await pool.end();
  }
}
